package htmltext

import (
	_ "embed"
	"sort"
	"strconv"
	"strings"
	"sync"
	"unicode/utf8"
)

// The str facts of the Python the bash lints ran on, for the code points from U+0080 (ASCII is in code):
// unicode.txt is generated by TestUnicodeTable (HTMLTEXT_REGEN=1) and its first line names that Python.
// A record is a kind and its entries: "lo-hi" ranges (e: NFKD holds only combining marks, a: isalnum,
// n: isdecimal), "cp:cp.cp" mappings (d: NFKD without combining marks, f: casefold) or code points (s: isspace).
//
//go:embed unicode.txt
var unicodeTxt string

type span struct{ lo, hi rune }

type tables struct {
	header                string
	erased, alnum, digits []span
	base, fold            map[rune]string
	space                 map[rune]bool
}

var data = sync.OnceValue(func() *tables {
	t := &tables{base: map[rune]string{}, fold: map[rune]string{}, space: map[rune]bool{}}
	for _, line := range strings.Split(strings.TrimSuffix(unicodeTxt, "\n"), "\n") {
		if strings.HasPrefix(line, "#") {
			t.header = line
			continue
		}
		f := strings.Fields(line)
		for _, e := range f[1:] {
			from, to, _ := strings.Cut(e, ":")
			lo, hi, _ := strings.Cut(from, "-")
			switch f[0] {
			case "e", "a", "n":
				r := span{hexRune(lo), hexRune(hi)}
				ranges := map[string]*[]span{"e": &t.erased, "a": &t.alnum, "n": &t.digits}[f[0]]
				*ranges = append(*ranges, r)
			case "d", "f":
				var b strings.Builder
				for _, h := range strings.Split(to, ".") {
					b.WriteRune(hexRune(h))
				}
				map[string]map[rune]string{"d": t.base, "f": t.fold}[f[0]][hexRune(from)] = b.String()
			case "s":
				t.space[hexRune(e)] = true
			default:
				panic("htmltext: corrupt unicode.txt record " + strconv.Quote(line))
			}
		}
	}
	return t
})

func hexRune(h string) rune {
	v, err := strconv.ParseUint(h, 16, 32)
	if err != nil {
		panic("htmltext: corrupt unicode.txt entry " + strconv.Quote(h))
	}
	return rune(v)
}

func in(rs []span, r rune) bool {
	i := sort.Search(len(rs), func(i int) bool { return rs[i].hi >= r })
	return i < len(rs) && rs[i].lo <= r
}

// IsSpace is str.isspace() of one code point (re's \s).
func IsSpace(r rune) bool {
	if r < 0x80 {
		return r == ' ' || r >= '\t' && r <= '\r' || r >= 0x1c && r <= 0x1f
	}
	return data().space[r]
}

// IsAlnum is str.isalnum() of one code point.
func IsAlnum(r rune) bool {
	if r < 0x80 {
		return r >= '0' && r <= '9' || r|0x20 >= 'a' && r|0x20 <= 'z'
	}
	return r != utf8.RuneError && in(data().alnum, r)
}

// IsDecimal is str.isdecimal() of one code point (re's \d).
func IsDecimal(r rune) bool {
	if r < 0x80 {
		return r >= '0' && r <= '9'
	}
	return in(data().digits, r)
}

// IsWord is re's \w for str patterns: isalnum or "_".
func IsWord(r rune) bool { return r == '_' || IsAlnum(r) }

// mapRunes rewrites each code point of s with m; a byte that is not UTF-8 (a lone surrogate a "\uD800"
// escape made, see Surrogate) is copied as is, as Python keeps the surrogate.
func mapRunes(s string, m func(r rune, b *strings.Builder) bool) string {
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); {
		r, n := utf8.DecodeRuneInString(s[i:])
		if (r == utf8.RuneError && n == 1) || !m(r, &b) {
			b.WriteString(s[i : i+n])
		}
		i += n
	}
	return b.String()
}

// StripMarks is "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)).
func StripMarks(s string) string {
	t := data()
	return mapRunes(s, func(r rune, b *strings.Builder) bool {
		switch {
		case r < 0x80:
			return false
		case r >= 0xAC00 && r <= 0xD7A3: // Hangul syllable: the algorithmic jamo, all starters
			v := r - 0xAC00
			b.WriteRune(0x1100 + v/588)
			b.WriteRune(0x1161 + v%588/28)
			if v%28 != 0 {
				b.WriteRune(0x11A7 + v%28)
			}
			return true
		}
		if d, ok := t.base[r]; ok {
			b.WriteString(d)
			return true
		}
		return in(t.erased, r)
	})
}

// CaseFold is str.casefold() (full case folding, "ß" -> "ss").
func CaseFold(s string) string {
	t := data()
	return mapRunes(s, func(r rune, b *strings.Builder) bool {
		if r >= 'A' && r <= 'Z' {
			b.WriteByte(byte(r) + 'a' - 'A')
			return true
		}
		if f, ok := t.fold[r]; ok {
			b.WriteString(f)
			return true
		}
		return false
	})
}

// Strip is str.strip(): leading and trailing str.isspace() code points removed.
func Strip(s string) string { return strings.TrimFunc(s, IsSpace) }

// CollapseSpace is re.sub(r"\s+", " ", s).
func CollapseSpace(s string) string {
	run := false
	return mapRunes(s, func(r rune, b *strings.Builder) bool {
		was := run
		if run = IsSpace(r); run && !was {
			b.WriteByte(' ')
		}
		return run
	})
}
